  UNION ALL SELECT 'ISO_2768_M','LINEAR_DIMENSIONS','over 30 up to 120',30,120,'N','Y',0.3,0.3,'±0.3',40
  UNION ALL SELECT 'ISO_2768_M','LINEAR_DIMENSIONS','over 120 up to 400',120,400,'N','Y',0.5,0.5,'±0.5',50
