-- ============================================================================
-- Optional Enquiry Material and Grade
-- Source: enquiry-material-grade-optional-migration.sql
-- ============================================================================

-- Make the Enquiry Material and Grade field optional.
-- Safe to import into an existing MySQL database through Adminer or phpMyAdmin.

SET @atech_material_grade_sql := IF(
  EXISTS(
    SELECT 1
    FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'marketing_enquiry_parts'
      AND COLUMN_NAME = 'material_and_grade'
      AND IS_NULLABLE = 'NO'
  ),
  'ALTER TABLE marketing_enquiry_parts MODIFY COLUMN material_and_grade VARCHAR(300) NULL',
  'SELECT 1'
);

PREPARE atech_material_grade_statement FROM @atech_material_grade_sql;
EXECUTE atech_material_grade_statement;
DEALLOCATE PREPARE atech_material_grade_statement;

-- ============================================================================
-- Cross-stage Enquiry Revision History
-- Source: enquiry-revision-timeline-migration.sql
-- ============================================================================

-- Extend Enquiry Revision History to include every marketing workflow stage.
-- Safe to import into an existing MySQL database through Adminer or phpMyAdmin.

SET @atech_enquiry_timeline_sql := IF(
  EXISTS(
    SELECT 1
    FROM information_schema.COLUMNS
    WHERE TABLE_SCHEMA = DATABASE()
      AND TABLE_NAME = 'marketing_enquiry_revisions'
      AND COLUMN_NAME = 'revision_action'
      AND COLUMN_TYPE NOT LIKE '%FEASIBILITY_SAVED%'
  ),
  'ALTER TABLE marketing_enquiry_revisions MODIFY COLUMN revision_action ENUM(''CREATED'', ''UPDATED'', ''SUBMITTED'', ''MIGRATED'', ''FEASIBILITY_SAVED'', ''FEASIBILITY_CLOSED'', ''WORKOUT_SAVED'', ''WORKOUT_COMPLETED'', ''QUOTATION_SAVED'', ''QUOTATION_FINALIZED'', ''ENQUIRY_ATTACHMENT_ADDED'', ''ENQUIRY_ATTACHMENT_UPDATED'', ''ENQUIRY_ATTACHMENT_REMOVED'') NOT NULL DEFAULT ''UPDATED''',
  'SELECT 1'
);

PREPARE atech_enquiry_timeline_statement FROM @atech_enquiry_timeline_sql;
EXECUTE atech_enquiry_timeline_statement;
DEALLOCATE PREPARE atech_enquiry_timeline_statement;

-- ============================================================================
-- Enquiry initial In Progress status
-- Source: enquiry-in-progress-status-migration.sql
-- ============================================================================

-- Draft enquiries remain in the Enquiry stage with an In Progress status.
-- Submitted enquiries already advance to Feasibility with the same status.
UPDATE marketing_enquiries
SET enquiry_status = 'IN_PROGRESS'
WHERE enquiry_status = 'ENQUIRED';

ALTER TABLE marketing_enquiries
  MODIFY enquiry_status VARCHAR(30)
  NOT NULL DEFAULT 'IN_PROGRESS';

