-- Receipt classification and customer-supplied material references for GRN inward.

ALTER TABLE goods_receipt_notes
  ADD COLUMN receipt_type VARCHAR(40) NOT NULL DEFAULT 'REGULAR_PURCHASE' AFTER grn_date,
  ADD COLUMN customer_id BIGINT UNSIGNED NULL AFTER supplier_id,
