ALTER TABLE goods_receipt_notes
  ADD COLUMN stock_posting_date DATE NULL AFTER received_by,
  ADD COLUMN stock_posted_by VARCHAR(50) NULL AFTER stock_posting_date;

ALTER TABLE goods_receipt_note_items
  ADD COLUMN warehouse_code VARCHAR(80) NULL AFTER quality_remarks,
