ALTER TABLE inventory_rejection_transaction
  MODIFY COLUMN transaction_type ENUM(
    'GRN_REJECTION','RETURN_TO_VENDOR','RETURN_TO_CUSTOMER','REWORK','SCRAP','DEVIATION_RELEASE',
    'ADJUSTMENT','RTV_SUBMITTED'
  ) NOT NULL;

ALTER TABLE return_to_vendor_documents
  MODIFY COLUMN document_status ENUM('PENDING_APPROVAL','APPROVED','ACKNOWLEDGED','DISPATCHED','CANCELLED')
    NOT NULL DEFAULT 'PENDING_APPROVAL';

ALTER TABLE return_to_vendor_documents ADD COLUMN approval_remarks VARCHAR(1000) NULL AFTER remarks;
ALTER TABLE return_to_vendor_documents ADD COLUMN approved_by VARCHAR(50) NULL AFTER approval_remarks;
ALTER TABLE return_to_vendor_documents ADD COLUMN approved_at DATETIME NULL AFTER approved_by;
