ALTER TABLE return_to_vendor_documents ADD COLUMN supplier_acknowledged_at DATETIME NULL AFTER supplier_acknowledged_by;
ALTER TABLE return_to_vendor_documents ADD COLUMN dispatched_by VARCHAR(50) NULL AFTER supplier_acknowledged_at;
