-- ============================================================================
-- Bulk Tooling issue, return and issued-location tracking
-- Source: tooling-bulk-issue-return-migration.sql
-- ============================================================================

-- Supports fast issued-tool location tracking for bulk tool issue and return.
-- Safe to run on an existing database after tooling-lifecycle-migration.sql.

-- Add indexes only when they are absent, so Adminer and the npm migration may
-- safely be run again after an interrupted deployment.
SET @tooling_bulk_issue_index_sql := IF(
  EXISTS(SELECT 1 FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tooling_stock_movements'
      AND INDEX_NAME='ix_tooling_issue_tracking'),
  'SELECT 1',
  'ALTER TABLE tooling_stock_movements ADD KEY ix_tooling_issue_tracking (tenant_id,movement_type,item_id,to_warehouse_code,to_bin_location,machine_reference,movement_date)'
);
PREPARE tooling_bulk_issue_index_statement FROM @tooling_bulk_issue_index_sql;
EXECUTE tooling_bulk_issue_index_statement;
DEALLOCATE PREPARE tooling_bulk_issue_index_statement;

SET @tooling_bulk_return_index_sql := IF(
  EXISTS(SELECT 1 FROM information_schema.STATISTICS
    WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tooling_stock_movements'
      AND INDEX_NAME='ix_tooling_return_tracking'),
  'SELECT 1',
  'ALTER TABLE tooling_stock_movements ADD KEY ix_tooling_return_tracking (tenant_id,movement_type,item_id,from_warehouse_code,from_bin_location,machine_reference,movement_date)'
);
PREPARE tooling_bulk_return_index_statement FROM @tooling_bulk_return_index_sql;
EXECUTE tooling_bulk_return_index_statement;
DEALLOCATE PREPARE tooling_bulk_return_index_statement;

-- ============================================================================
-- Item Master UOM and Raw Material category cleanup
-- Source: item-master-uom-rm-category-cleanup-migration.sql
-- ============================================================================

-- Keep one kilogram UOM and retire obsolete Raw Material categories.
-- Historical items remain intact; their UOM references are normalized to KG.
START TRANSACTION;

INSERT INTO uom_master (uom_code,uom_name,active_flag,created_by)
VALUES ('KG','Kilogram','Y','SYSTEM')
ON DUPLICATE KEY UPDATE uom_name=VALUES(uom_name),active_flag='Y';

SET @kg_uom_id := (
  SELECT uom_id
  FROM uom_master
  WHERE UPPER(TRIM(uom_code))='KG'
  ORDER BY uom_id
  LIMIT 1
);

UPDATE item_master I
JOIN uom_master U ON U.uom_id=I.uom_id
SET I.uom_id=@kg_uom_id
WHERE @kg_uom_id IS NOT NULL
  AND UPPER(TRIM(U.uom_code))='KGS';

UPDATE item_specification_value V
JOIN uom_master U ON U.uom_id=V.uom_id
SET V.uom_id=@kg_uom_id
WHERE @kg_uom_id IS NOT NULL
  AND UPPER(TRIM(U.uom_code))='KGS';

UPDATE uom_master
SET active_flag='N'
WHERE UPPER(TRIM(uom_code))='KGS';

-- Do not delete legacy categories that may be linked to existing items.
UPDATE item_type_master T
JOIN item_group_master G ON G.item_group_id=T.item_group_id
SET T.active_flag='N',T.updated_by='SYSTEM'
WHERE G.group_code='RM'
  AND UPPER(TRIM(T.type_name)) IN (
    'ROUND BAR','SQUARE BAR','SQUARE ROD','PROFILE','TERMINAL','POWDER','EXTRUSION'
  );

COMMIT;

-- ============================================================================
-- Production inventory control, work-order WIP and rejection disposition
-- Source: inventory-control-migration.sql
-- ============================================================================

-- Production inventory control foundation.
-- This migration is additive: existing GRN, customer material, tooling and gauge
-- balances remain valid and are classified as GENERAL / AVAILABLE until moved.

CREATE TABLE IF NOT EXISTS inventory_subinventory_master (
  inventory_subinventory_master_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  tenant_id VARCHAR(64) NOT NULL,
  subinventory_code VARCHAR(40) NOT NULL,
  subinventory_name VARCHAR(120) NOT NULL,
  inventory_purpose VARCHAR(30) NOT NULL DEFAULT 'STOCK',
  active_flag ENUM('Y','N') NOT NULL DEFAULT 'Y',
  created_by VARCHAR(50) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_by VARCHAR(50) NULL,
  updated_at DATETIME NULL,
  PRIMARY KEY (inventory_subinventory_master_id),
  UNIQUE KEY uq_inventory_subinventory (tenant_id,subinventory_code),
  KEY ix_inventory_subinventory_active (tenant_id,active_flag)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS inventory_stock_status_master (
  inventory_stock_status_master_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  tenant_id VARCHAR(64) NOT NULL,
  stock_status_code VARCHAR(40) NOT NULL,
  stock_status_name VARCHAR(120) NOT NULL,
  available_for_issue_flag ENUM('Y','N') NOT NULL DEFAULT 'N',
  active_flag ENUM('Y','N') NOT NULL DEFAULT 'Y',
  created_by VARCHAR(50) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (inventory_stock_status_master_id),
  UNIQUE KEY uq_inventory_stock_status (tenant_id,stock_status_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO inventory_subinventory_master
  (tenant_id,subinventory_code,subinventory_name,inventory_purpose,active_flag,created_by)
SELECT T.tenant_id,S.subinventory_code,S.subinventory_name,S.inventory_purpose,'Y','SYSTEM'
FROM (
  SELECT 'DEFAULT' AS tenant_id
  UNION SELECT DISTINCT tenant_id FROM inventory_stock_balance
  UNION SELECT DISTINCT tenant_id FROM location_master
) T
CROSS JOIN (
  SELECT 'GENERAL' AS subinventory_code,'Legacy / unclassified stock' AS subinventory_name,'STOCK' AS inventory_purpose
  UNION ALL SELECT 'RM','Raw material','STOCK'
  UNION ALL SELECT 'FG','Finished goods','STOCK'
  UNION ALL SELECT 'WIP','Work in progress','WIP'
  UNION ALL SELECT 'MTR','Material return','RETURN'
  UNION ALL SELECT 'PRR','Production return','RETURN'
  UNION ALL SELECT 'MATERIAL_REJECTION','Material rejection','REJECTION'
  UNION ALL SELECT 'PROCESS_REJECTION','Process rejection','REJECTION'
  UNION ALL SELECT 'SCRAP','Scrap','SCRAP'
  UNION ALL SELECT 'TOOLS','Tools and fixtures','TOOLING'
  UNION ALL SELECT 'GAUGES','Gauges and instruments','GAUGE'
) S
WHERE 1=1
ON DUPLICATE KEY UPDATE subinventory_name=VALUES(subinventory_name),inventory_purpose=VALUES(inventory_purpose),active_flag='Y';

INSERT INTO inventory_stock_status_master
  (tenant_id,stock_status_code,stock_status_name,available_for_issue_flag,active_flag,created_by)
SELECT T.tenant_id,S.stock_status_code,S.stock_status_name,S.available_for_issue_flag,'Y','SYSTEM'
FROM (
  SELECT 'DEFAULT' AS tenant_id
  UNION SELECT DISTINCT tenant_id FROM inventory_stock_balance
  UNION SELECT DISTINCT tenant_id FROM location_master
) T
CROSS JOIN (
  SELECT 'AVAILABLE' AS stock_status_code,'Available for issue' AS stock_status_name,'Y' AS available_for_issue_flag
  UNION ALL SELECT 'HOLD','Quality or stores hold','N'
  UNION ALL SELECT 'ISSUED','Issued to work order','N'
  UNION ALL SELECT 'QUARANTINE','Quarantine','N'
  UNION ALL SELECT 'REWORK','Under rework','N'
  UNION ALL SELECT 'REJECTED','Rejected','N'
  UNION ALL SELECT 'SCRAP','Scrap pending disposal','N'
  UNION ALL SELECT 'RETURN_PENDING','Awaiting external return','N'
) S
WHERE 1=1
ON DUPLICATE KEY UPDATE stock_status_name=VALUES(stock_status_name),available_for_issue_flag=VALUES(available_for_issue_flag),active_flag='Y';

ALTER TABLE inventory_stock_balance
  ADD COLUMN sub_inventory_code VARCHAR(40) NOT NULL DEFAULT 'GENERAL' AFTER warehouse_code;
ALTER TABLE inventory_stock_balance
  ADD COLUMN stock_status VARCHAR(40) NOT NULL DEFAULT 'AVAILABLE' AFTER bin_location;
ALTER TABLE inventory_stock_balance
  ADD COLUMN work_order_reference VARCHAR(120) NOT NULL DEFAULT '' AFTER batch_serial_number;
ALTER TABLE inventory_stock_balance
  ADD COLUMN quantity_reserved DECIMAL(18,3) NOT NULL DEFAULT 0.000 AFTER quantity_on_hand;

ALTER TABLE inventory_stock_transaction
  MODIFY COLUMN transaction_type VARCHAR(60) NOT NULL;
ALTER TABLE inventory_stock_transaction
  MODIFY COLUMN grn_id BIGINT UNSIGNED NULL;
ALTER TABLE inventory_stock_transaction
  MODIFY COLUMN grn_item_id BIGINT UNSIGNED NULL;
ALTER TABLE inventory_stock_transaction
  ADD COLUMN sub_inventory_code VARCHAR(40) NOT NULL DEFAULT 'GENERAL' AFTER warehouse_code;
ALTER TABLE inventory_stock_transaction
  ADD COLUMN stock_status VARCHAR(40) NOT NULL DEFAULT 'AVAILABLE' AFTER bin_location;
ALTER TABLE inventory_stock_transaction
  ADD COLUMN work_order_reference VARCHAR(120) NOT NULL DEFAULT '' AFTER batch_serial_number;
ALTER TABLE inventory_stock_transaction
  ADD COLUMN inventory_movement_document_id BIGINT UNSIGNED NULL AFTER grn_item_id;

ALTER TABLE inventory_stock_balance DROP INDEX uq_inventory_stock_balance_location;
ALTER TABLE inventory_stock_balance ADD UNIQUE KEY uq_inventory_stock_balance_control
  (tenant_id,plant_id,item_id,warehouse_code,sub_inventory_code,bin_location,batch_serial_number,work_order_reference,stock_status,stock_owner_type,stock_owner_id);
ALTER TABLE inventory_stock_balance ADD KEY ix_inventory_stock_balance_control
  (tenant_id,warehouse_code,sub_inventory_code,stock_status,stock_owner_type);
ALTER TABLE inventory_stock_transaction ADD KEY ix_inventory_stock_transaction_control
